exercises.solution:
const mapa = new Map();
mapa.set("x", 10);
mapa.set("y", 20);
mapa.set("z", 30);

console.log(mapa.size);     // 3
console.log(mapa.get("y")); // 20

const kluczObiekt = { id: 99 };
const mapa = new Map();
mapa.set(kluczObiekt, "metadane");

console.log(mapa.get(kluczObiekt)); // "metadane"

const mapa = new Map([["x", 10], ["y", 20], ["z", 30]]);
mapa.delete("x");
console.log(mapa.size); // 2

const mapa = new Map([["a", 1], ["b", 2]]);
console.log(mapa.has("a")); // true
console.log(mapa.has("z")); // false

const mapa = new Map();
mapa.set(1, "liczba");
mapa.set("1", "string");
mapa.set(true, "boolean");

console.log(mapa.get(1));    // "liczba"
console.log(mapa.get("1"));  // "string"
console.log(mapa.get(true)); // "boolean"
console.log(mapa.size);      // 3 - trzy ROZNE klucze

function walidujFormularz() {}
const konfiguracja = { debug: true };

const mapa = new Map();
mapa.set(walidujFormularz, "walidacja formularza");
mapa.set(konfiguracja, "konfiguracja aplikacji");

console.log(mapa.get(walidujFormularz)); // "walidacja formularza"
console.log(mapa.get(konfiguracja));     // "konfiguracja aplikacji"

const mapa = new Map();
mapa.set("klucz", "wartosc");

console.log(mapa["klucz"]); // undefined - notacja nawiasowa NIE dziala z Map
console.log(mapa.get("klucz")); // "wartosc" - POPRAWNY sposob

// Map to CALKOWICIE osobny typ danych (nie "ulepszony obiekt"), z wlasnym
// zestawem metod (.get/.set/.has/.delete). Notacja nawiasowa ([]) jest
// mechanizmem specyficznym dla ZWYKLYCH obiektow, ktory na instancji Map
// probuje odczytac zwykla, publiczna wlasciwosc o nazwie "klucz" (ktorej
// Map nie ma), a nie wpis z wewnetrznej kolekcji par klucz-wartosc.
